handlers = { "search": search_handler, "read_file": read_file_handler }

def route(request):
    handler = handlers.get(request["params"]["name"])
    if handler is None:
        return error_response(request["id"], "unknown tool")
    return handler(request["params"]["arguments"])

def on_response(message):
    entry = pending_requests.pop(message["id"], None)
    if entry is None:
        return  # stale or unknown id, discard
    entry.resolve(message)
